<?php
header('Content-Type: application/json; charset=utf-8'); include('../../../conexi.php'); $link = Conectarse();
if (!isset($_COOKIE['id_usuarios'])) { http_response_code(401); echo json_encode(['ok'=>false,'mensaje'=>'Sesión caducada.']); exit; }
function uuidV4() { $b = random_bytes(16); $b[6] = chr((ord($b[6]) & 15) | 64); $b[8] = chr((ord($b[8]) & 63) | 128); $h = bin2hex($b); return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20); }
$id = isset($_POST['id_cliente_frecuente']) ? (int) $_POST['id_cliente_frecuente'] : 0;
$nombre = trim($_POST['nombre_cliente']); $paterno = trim($_POST['apellidop_cliente']); $materno = trim($_POST['apellidom_cliente']); $pais = trim($_POST['pais_cliente']); $clave = trim($_POST['clave_pais_cliente']); $telefono = trim($_POST['telefono_cliente']); $correo = trim($_POST['correo_cliente']); $rfc = strtoupper(trim($_POST['rfc_cliente'])); $estatus = $_POST['estatus_cliente'] === 'Inactivo' ? 'Inactivo' : 'Activo'; $observaciones = trim($_POST['observaciones']);
if ($nombre === '' || $pais === '' || $clave === '' || $telefono === '') { echo json_encode(['ok'=>false,'mensaje'=>'Nombre, país, clave y teléfono son obligatorios.']); exit; }
$dup = mysqli_prepare($link, 'SELECT id_cliente_frecuente FROM clientes_frecuentes WHERE clave_pais_cliente = ? AND telefono_cliente = ? AND id_cliente_frecuente <> ? LIMIT 1'); mysqli_stmt_bind_param($dup, 'ssi', $clave, $telefono, $id); mysqli_stmt_execute($dup); $existe = mysqli_fetch_assoc(mysqli_stmt_get_result($dup)); mysqli_stmt_close($dup);
if ($existe) { echo json_encode(['ok'=>false,'mensaje'=>'Ya existe un cliente con esa clave y teléfono.']); exit; }
if ($id > 0) { $q = mysqli_prepare($link, 'UPDATE clientes_frecuentes SET nombre_cliente=?, apellidop_cliente=?, apellidom_cliente=?, pais_cliente=?, clave_pais_cliente=?, telefono_cliente=?, correo_cliente=?, rfc_cliente=?, estatus_cliente=?, observaciones=? WHERE id_cliente_frecuente=?'); mysqli_stmt_bind_param($q,'ssssssssssi',$nombre,$paterno,$materno,$pais,$clave,$telefono,$correo,$rfc,$estatus,$observaciones,$id); }
else { $uuid = uuidV4(); $q = mysqli_prepare($link, 'INSERT INTO clientes_frecuentes (uuid_cliente,nombre_cliente,apellidop_cliente,apellidom_cliente,pais_cliente,clave_pais_cliente,telefono_cliente,correo_cliente,rfc_cliente,estatus_cliente,observaciones) VALUES (?,?,?,?,?,?,?,?,?,?,?)'); mysqli_stmt_bind_param($q,'sssssssssss',$uuid,$nombre,$paterno,$materno,$pais,$clave,$telefono,$correo,$rfc,$estatus,$observaciones); }
$ok = mysqli_stmt_execute($q); $mensaje = mysqli_stmt_error($q); mysqli_stmt_close($q); echo json_encode(['ok'=>$ok,'mensaje'=>$ok?'Guardado correctamente.':$mensaje]);
